// Set these values to the same source, collection and checkpoint used by the initial snapshot workflow.
const sourceKey = 'your_organisation';
const collection = 'openbesluitvorming';
const checkpointId = '00000000-0000-5000-8000-000000000001';
return [{ json: { runId: `openbesluitvorming-sync-${Date.now()}`, sourceKey, collection, checkpointId, qdrantBase: 'http://qdrant:6333', vectorSize: 3072, changesLimit: 500 } }];

const cfg = $('2. Configure Delta Sync').first().json;
const payload = $input.first().json?.result?.payload || $input.first().json?.payload || null;
if (!payload || payload.kind !== 'ori_checkpoint' || payload.source_key !== cfg.sourceKey) throw new Error('Initial snapshot checkpoint is missing or belongs to a different source');
// The delta workflow deliberately stays idle until the snapshot cursor has reached the end.
if (payload.completed !== true) return [];
const cursor = payload.sync_changes_cursor || payload.changes_cursor || null;
if (!cursor) throw new Error('Initial snapshot did not persist X-Changes-Cursor; do not start delta synchronisation');
return [{ json: { ...cfg, checkpoint: payload, changesCursor: cursor } }];

const cfg = $('4. Guard Snapshot Completion And Changes Cursor').first().json;
const response = $input.first().json || {};
const headers = response.headers || {};
const header = name => headers[name] || headers[name.toLowerCase()] || null;
const body = String(response.body || response.data || '');
const records = body.split('\n').filter(Boolean).map(line => { try { return JSON.parse(line); } catch { return null; } }).filter(Boolean);
const upserts = records.filter(record => record.op === 'upsert' && record.entity_type === 'Document');
const deletes = records.filter(record => record.op === 'delete' && record.entity_type === 'Document');
const nextCursor = header('x-next-cursor') || cfg.changesCursor;
const hasMore = String(header('x-has-more')).toLowerCase() === 'true';
return [{ json: { ...cfg, records, upserts, deletes, nextCursor, hasMore, change_page_records: records.length } }];

const page = $('6. Parse Upserts And Tombstones').first().json;
function pointId(input){let h1=0xdeadbeef,h2=0x41c64e6d,h3=0x12345678,h4=0x87654321;for(const c of input){const x=c.charCodeAt(0);h1=Math.imul(h1^x,2654435761);h2=Math.imul(h2^x,1597334677);h3=Math.imul(h3^x,2246822507);h4=Math.imul(h4^x,3266489909)}const hex=[h1,h2,h3,h4].map(x=>(x>>>0).toString(16).padStart(8,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-5${hex.slice(13,16)}-${((parseInt(hex.slice(16,18),16)&0x3f)|0x80).toString(16)}${hex.slice(18,20)}-${hex.slice(20,32)}`;}
const ids = page.deletes.map(record => pointId(String(record.entity_id))).filter(Boolean);
return [{ json: { ...page, deletePointIds: ids, deleteBody: { points: ids } } }];

const page = $('6. Parse Upserts And Tombstones').first().json;
const prior = page.checkpoint;
const now = new Date().toISOString();
const checkpoint = { ...prior, sync_changes_cursor: page.nextCursor, sync_last_at: now, sync_last_records: page.change_page_records, sync_last_upserts: page.upserts.length, sync_last_deletes: page.deletes.length, sync_has_more: page.hasMore, sync_runs: Number(prior.sync_runs || 0) + 1 };
const point = { id: page.checkpointId, vector: new Array(page.vectorSize).fill(0), payload: checkpoint };
return [{ json: { ...page, checkpoint, checkpointPoint: point } }];

const page = $('12. Commit Delta Cursor Only After Apply').first().json;
console.log(JSON.stringify({ event: 'delta_page_committed', run_id: page.runId, source_key: page.sourceKey, changes_cursor: page.checkpoint.sync_changes_cursor, records: page.change_page_records, upserts: page.upserts.length, deletes: page.deletes.length, has_more: page.hasMore }));
return [{ json: { status: page.hasMore ? 'more_changes_pending' : 'caught_up', source_key: page.sourceKey, records: page.change_page_records, upserts: page.upserts.length, deletes: page.deletes.length, next_changes_cursor: page.checkpoint.sync_changes_cursor } }];
